namespace MmaManager.Core.Sim.Generation.Origins;

public static partial class OriginsChapters
{
    // ===================== ERA 1: THE SPECTACLE (1993-1996) =====================
    private static OriginsChapter[] Era1() => new[]
    {
        C("crucible-first-night", 1, "Who Wins? Eight Men, One Night, Los Angeles", 0, 4, A(),
            "The first Crucible Challenge card goes out on pay-per-view in the opening weeks of 1993.",
            Dated(),
            A("Media:PpvCarrier"),
            A("Tapes of the card sell through mail-order ads and video shops: a second income line from this night."),
            null, null,
            N("Eight men, one question: who wins?",
              "{Year}. At the Pico Sports Pavilion in Los Angeles, Len Pastor's Crucible Challenge puts eight men from eight disciplines into one night's bracket: a boxer, a freestyle wrestler, a sumo veteran, a quiet jiu-jitsu teacher. One round of up to twenty minutes a fight, no weight classes, and a draw sends both men home. Keystone Event Network carries it into living rooms at a price, and video shops are told to expect tapes within the month. The critics are baffled and the telephone lines are busy. Pastor's question, written on a legal pad a year ago, is for one evening the most argued-over thing on American television."),
            "Crucible Challenge's first night airs on pay-per-view: eight men, no weight classes, one question.",
            "Day-one chapter, narrated from the world's view because the promotions are named. It fires for whoever the player is."),

        C("shinken-and-duelo-open", 1, "A Bow in Tokyo, a Shout in Rio", 0, 6, A(),
            "The Shinken Fighting Association holds its first Friday card and Duelo Livre's Saturday garage nights are filmed for the first time.",
            Dated(),
            A(),
            A("The roped-ring, bowing-crowd style and the gym-duel style are established as separate ideas of the sport.",
              "Rope-escape rules and judges exist at Shinken from day one; the garage format has neither."),
            null, null,
            N("Two rooms, two ideas, one sport with no name",
              "{Year}. On the same winter weekend, two rooms on opposite sides of the planet open their doors to a sport nobody has named. In Tokyo, Kosaku Hiyama's Shinken Fighting Association fills Eitoku Hall with men who bow to the ring, to one another and to a crowd that bows back; the bell, the ropes and the referee's bow tie come from wrestling, the script does not. In Rio, Anibal Sampaio's Duelo Livre rolls up a garage door in Tijuca and lets two academies settle an old argument in one round with a cash box by the ramp. A borrowed camcorder records it. Neither promoter has heard of the other."),
            "Tokyo bows and Rio shouts: Shinken and Duelo Livre hold their opening cards.",
            "Day-one chapter naming both founding promotions; no player/rival split."),

        C("first-backers", 1, "Somebody Will Pay to Be Seen Here", 1, 14, A("crucible-first-night"),
            "The first promotion to sign a sponsor: a local business first, then a mail-order supplement house and a martial-arts magazine buying space.",
            First("SignSponsor:Local"),
            A("Sponsor:Local", "Sponsor:Supplement"),
            A("Fringe sponsors pay small per-event fees and ask for little; the first logos appear on the canvas."),
            N("{Partner} puts its name on {Org}'s canvas",
              "It is not a bank and it is not a household name, but {Partner} has paid to hang a banner over {Org}'s ring, and that makes {Org} the first promotion in the world with a sponsor. {Founder} frames the cheque, then spends the next week quietly working out how many cards it takes to earn the next one. The fringe is where every new sport begins: gyms, garages and mail-order men who sell strength by the tub. Others will notice who got there first."),
            N("{Partner} backs {Org}",
              "A small outfit called {Partner} has signed to back {Org}, and the trade papers, such as they are, treat it as news. Rival promoters read it as a sign that somebody believes there is a business here. Fringe money, mail-order money, the sort of advertiser who sells in the back pages of martial-arts magazines. It is not much. It is the first, and {Org} now has a banner and a head start."),
            N("The back pages find a customer",
              "{Year}. A sport with no name and no rules to speak of finds its first advertisers in the places nobody respectable looks. A tyre shop buys a banner. A mail-order supplement house, selling powders by post to men who want to be stronger, buys a corner of a poster. A martial-arts magazine trades full-page adverts for ringside seats. The sums are tiny, a few hundred dollars a night, but a promoter who can show a banner can show a bank manager, and the whole world of small business starts to wonder."),
            "First backers: a local business and the back-page supplement houses put money behind a night of fights."),

        C("first-star", 1, "The First Name People Ask For", 6, 30, A("crucible-first-night"),
            "A fighter's fame crosses a first threshold: strangers know the name, and the poster carries a face.",
            World("FighterFameAtLeast", 45),
            A(),
            A("Fighters can begin to carry star power; the first poster with a single face on it."),
            N("{Fighter} is the face of {Org}",
              "People who have never watched a fight now know {Fighter}'s name. Taxi drivers ask about the next night in {City}. {Org}'s poster used to say eight disciplines; the next one will say a single name, and {Founder} knows what that is worth. Fame in a sport with no stars is a strange new weight to carry, and {Fighter} is carrying it with an odd, steady calm. The audience has found someone to follow, and everyone else must now find someone to beat him."),
            N("{Fighter} of {Org} becomes the name on every lip",
              "Somewhere between one card and the next, {Fighter} stopped being a bracket and became a person. Fans who never cared about disciplines now ask when {Fighter} fights again, and the rest of the business is reading the figures. {Org} has the first genuine attraction the sport has had. The challenge for every other promoter is simple and expensive: find one of your own, or find a way to take his."),
            N("A sport finds its first star",
              "{Year}. Every new thing needs a face. After a season of nameless brackets and interchangeable styles, one fighter, {Fighter}, is suddenly known beyond the hall: recognised on the street, quoted in the sports pages, asked for by name at the video shop. Nobody planned it. The man himself looks bewildered by it. Promoters, who have spent a year selling the idea, discover that people prefer to buy a person. The poster designers will not forget the lesson."),
            "A first star: {Fighter} becomes a name that strangers ask for."),

        C("rivals-appear", 1, "Everybody Has a Better Idea", 9, 36, A("crucible-first-night"),
            "The world's fourth promotion opens its doors, or the first newcomer outside the founding three is staged.",
            World("PromotionsAtLeast", 4),
            A("NewPromotions"),
            A("New promotions can be founded and appear on the schedule; a startup picks a lane the others do not own."),
            N("{Org} opens, with ideas of its own",
              "{Founder} says {Org} is not copying anyone: no bracket, no garage, no ropes, but a plain card with proper matchmaking and people who have trained for it. The first night in {City} sells fewer seats than hoped and more than expected. Being the newest promotion in a sport this young is a curious position: everyone you meet is still working out what the thing is, and you have as good a claim as any to tell them."),
            N("A new name on the map: {Org}",
              "{Org} has opened in {City}, and {Founder} has made it clear to anyone who will listen that the sport belongs to nobody yet. The older promotions have noticed. Some say it will not last a year; others quietly book a scout for the first night. In a business this new, every rival is also a source of fighters and a source of ideas."),
            N("The sport grows a fourth promotion",
              "{Year}. Within a few seasons of the first cards, imitators and rivals are everywhere. A gym owner in one city, a nightclub manager in another and a retired boxing promoter in a third each decide that the thing can be done better, or at least nearer to home. None has much money. All have a view about rules. The world's three founding promotions are now four, then five, and for the first time a fighter can ask who will pay him more."),
            "A fourth promotion opens: the sport is no longer three rooms."),

        C("style-upset", 1, "The Myth of the Unbeatable Art Cracks", 12, 40, A("first-star"),
            "A famous specialist is beaten by a lesser-known man from a different discipline.",
            World("UpsetOfStar", 30),
            A(),
            A("Style matchups become a live story; the market begins to prefer fighters who know a second art."),
            N("{Fighter} ends a legend's legend",
              "For years, people said no man in the building could hold a champion of that art. {Fighter} of {Org} did not argue; he simply closed the distance, changed the question and waited. The finish took under two minutes. In the dressing room the loser asked what the move was called, and nobody knew. {Founder} watched from the second row and began quietly reconsidering every brief about who should fight whom."),
            N("{Fighter} of {Org} upsets the unbeatable",
              "It was supposed to be a showcase: a famous champion of one art and an unknown from another. Instead {Fighter} of {Org} spent four minutes proving that a reputation is only a theory. The crowd in {City} went quiet, then loud. Every academy in the country will spend the winter arguing about why. Every promoter will spend it looking for the next unknown."),
            N("The first rule of every art is broken",
              "{Year}. For three seasons every discipline has been sure that it was the answer. Then a celebrated specialist, undefeated in his own world, is caught by a man whose art he has never faced, and the whole idea of a perfect style wobbles. Gyms that taught only one thing begin to add a second. Fighters who looked invincible start to look narrow. Nobody calls it cross-training yet. The idea has been planted all the same."),
            "The first death of a style: a famous specialist is beaten by a man from another art."),

        C("scene-low-countries-canada", 1, "Amsterdam and Canada Open Their Doors", 15, 48, A("first-star"),
            "The first promotion to hold a card in a new country (the Netherlands or Canada first).",
            First("HoldEventInNewCountry"),
            A("CountryScene:NED", "CountryScene:CAN"),
            A("The scenes in the Netherlands and Canada wake: local shows, local talent, local venues."),
            N("{Org} takes the sport to {City}, {Country}",
              "The first card outside home territory is a leap of faith, and {Org} has made it. {City} has never seen anything like it. Local fighters line up to ask for a place on the bill. The hall is rented, the posters are in the wrong language and the crowd arrives anyway. {Founder} comes home with a bruised budget and a fat folder of names, and a certainty that the sport does not belong to any one country."),
            N("{Org} crosses the border to {City}",
              "{Org} has taken a card to {City}, {Country}, the first promotion to run a night in a country that has never seen one. Local gyms are already booking tickets. The stunt will not pay for itself; the folder of local fighters might. Rivals at home admit, under their breath, that they should have thought of it first. The posters arrive late, the translator is a cousin and the box office is a card table. By any measure it is a success."),
            N("The sport leaves home: Amsterdam and Canada",
              "{Year}. The kickboxing halls of Amsterdam, where men have fought with hands and feet for a generation, hear about the new nights and want in. In Canada, the hockey towns of Ontario and Quebec fill rinks for a card that has never been seen outside the American television. Within months both countries have a scene of their own: a handful of local promoters, a ring in a rented arena and a fighter or two whom the home promotions would love to meet."),
            "Scenes wake in the Netherlands and Canada: the sport has left home."),
    };
}
